INSERT INTO `itinerario_destino` VALUES (31,1,'Día 1','Llegada y bienvenida','Recepción en el aeropuerto y traslado al hotel. Tarde libre para instalarse y disfrutar de la playa.',0),(32,1,'Día 2','Recorrido por la Riviera Maya','Excursión de día completo a Tulum y al cenote Azul, con almuerzo incluido.',1),(33,1,'Día 3','Día de playa y relax','Jornada libre para disfrutar del resort, actividades opcionales y piscina.',2),(34,1,'Día 4','Aventura acuática','Snorkel en el Parque Nacional de Cancún y paseo en catamarán al atardecer.',3),(35,1,'Día 5','Regreso a casa','Mañana libre y traslado al aeropuerto según tu vuelo.',4),(36,2,'Día 1','Bienvenida en la ciudad luz','Llegada a París, traslado al hotel y paseo de bienvenida por el Sena al anochecer.',0),(37,2,'Día 2','Louvre y corazón histórico','Visita guiada al Museo del Louvre y recorrido por la Île de la Cité, con entrada a Notre-Dame.',1),(38,2,'Día 3','Torre Eiffel y Montmartre','Ascenso a la Torre Eiffel, tarde en Montmartre y cena en un bistrot tradicional.',2),(39,2,'Día 4','Versalles y jardines reales','Excursión de medio día al Palacio de Versalles y tarde libre para descubrir el Barrio Latino.',3),(40,2,'Día 5','Compras y despedida','Mañana libre para compras en Saint-Germain y traslado al aeropuerto para el vuelo de regreso.',4),(41,3,'Día 1','Llegada y bienvenida','Recepción en el aeropuerto y traslado al hotel. Tarde libre para instalarse.',0),(42,3,'Día 2','Dubái moderno','Visita al Burj Khalifa, el Dubai Mall y la fuente danzante.',1),(43,3,'Día 3','Aventura en el desierto','Safari en 4x4, paseo en camello y cena beduina con show de danza.',2),(44,3,'Día 4','Dubái histórico y costero','Recorrido por el Dubai Creek, el zoco de oro y paseo en dhow por la Marina.',3),(45,3,'Día 5','Regreso a casa','Mañana libre y traslado al aeropuerto según tu vuelo.',4),(46,4,'Día 1','Llegada a Tokio','Recepción en el aeropuerto y traslado al hotel. Tarde libre en Shinjuku.',0),(47,4,'Día 2','Tokio tradicional','Templo Senso-ji, barrio de Asakusa y paseo por los jardines del Palacio Imperial.',1),(48,4,'Día 3','Tokio moderno','Shibuya, Harajuku y tarde en Akihabara.',2),(49,4,'Día 4','Excursión a Hakone','Día completo con vistas al monte Fuji y baños termales tradicionales.',3),(50,4,'Día 5','Regreso a casa','Mañana libre para las últimas compras y traslado al aeropuerto.',4),(51,5,'Día 1','Llegada y bienvenida','Recepción en el aeropuerto y traslado al hotel frente al mar. Tarde libre en la playa.',0),(52,5,'Día 2','Piscinas naturales','Paseo en jangada hasta los arrecifes de Pajuçara.',1),(53,5,'Día 3','Praia do Francês','Día de playa y surf en una de las costas más lindas de Alagoas.',2),(54,5,'Día 4','Porto de Galinhas','Excursión de día completo con snorkel y compras de artesanías.',3),(55,5,'Día 5','Regreso a casa','Mañana libre y traslado al aeropuerto según tu vuelo.',4),(56,6,'Día 1','Llegada y bienvenida','Recepción en el aeropuerto y traslado al hotel. Tarde libre en la Marienplatz.',0),(57,6,'Día 2','Múnich histórica','Ayuntamiento Nuevo, Frauenkirche y mercado de Viktualienmarkt.',1),(58,6,'Día 3','Excursión a Neuschwanstein','Día completo al castillo de los cuentos de hadas bávaros.',2),(59,6,'Día 4','Cultura y cerveza','Recorrido por una cervecería tradicional y tarde libre en el Englischer Garten.',3),(60,6,'Día 5','Regreso a casa','Mañana libre y traslado al aeropuerto según tu vuelo.',4);
